          "sql": "SELECT c.service_name AS caller, c.attr_http_response_status_code AS caller_sees_status, s.service_name AS callee, s.attr_http_response_status_code AS callee_sends_status, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id WHERE c.service_name = 'ts-preserve-service' AND c.attr_span_kind = 'Client' AND s.service_name = 'ts-seat-service' GROUP BY ALL",
          "claim": "Preserve's POST calls to seat-service all show status 401 on the client side, while seat-service's own server spans return 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name = 'ts-preserve-service' AND attr_span_kind IN ('Server','Client') GROUP BY ALL ORDER BY n DESC",
          "claim": "Every preserve request in the abnormal window ends in a 500 server span, with the 401 seen on its outgoing seat call."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) AS n, any_value(message) AS example FROM abnormal_logs WHERE service_name = 'ts-preserve-service' AND level = 'SEVERE' GROUP BY ALL",
          "claim": "Preserve logs 537 SEVERE entries reporting HttpClientErrorException Unauthorized 401 from its downstream call."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS upstream, p.span_name, p.attr_http_response_status_code AS upstream_status, s.service_name AS downstream, s.attr_http_response_status_code AS downstream_status, count(*) AS n FROM abnormal_traces s JOIN abnormal_traces p ON p.span_id = s.parent_span_id AND p.trace_id = s.trace_id WHERE s.service_name = 'ts-preserve-service' AND s.attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Preserve's 500 server responses are received by ts-ui-dashboard's preserve endpoint, which reports the failure to users."
        }
      ]
    }
  ]
}
